<template id="purchaseLineTemplate"><tr><td><select name="items[INDEX][product_id]" class="purchase-product"><option value="">Custom cost line</option>@foreach($products as $product)<option value="{{ $product->id }}" data-name="{{ e($product->name) }}" data-cost="{{ $product->cost_price }}" data-unit="{{ e($product->unit) }}" data-vat="{{ $product->vat_rate }}">{{ $product->name }} — OMR {{ number_format($product->cost_price,3) }}</option>@endforeach</select><input name="items[INDEX][description]" class="purchase-description" placeholder="Description" required></td><td><input name="items[INDEX][quantity]" type="number" min="0.001" step="0.001" value="1" required></td><td><input name="items[INDEX][unit]" class="purchase-unit" value="Unit" required></td><td><input name="items[INDEX][unit_cost]" class="purchase-cost" type="number" min="0" step="0.001" value="0" required></td><td><input name="items[INDEX][vat_rate]" class="purchase-vat" type="number" min="0" max="100" step="0.01" value="5" required></td><td><button type="button" class="remove-line">×</button></td></tr></template>
<script>document.addEventListener('DOMContentLoaded',()=>{let n=0,b=document.getElementById('purchaseLines'),t=document.getElementById('purchaseLineTemplate');function add(){let x=t.innerHTML.replaceAll('INDEX',n++);b.insertAdjacentHTML('beforeend',x);let r=b.lastElementChild,s=r.querySelector('.purchase-product');s.addEventListener('change',()=>{let o=s.options[s.selectedIndex];if(s.value){r.querySelector('.purchase-description').value=o.dataset.name;r.querySelector('.purchase-unit').value=o.dataset.unit;r.querySelector('.purchase-cost').value=o.dataset.cost;r.querySelector('.purchase-vat').value=o.dataset.vat}});r.querySelector('.remove-line').onclick=()=>{if(b.children.length>1)r.remove()}}add();document.getElementById('addPurchaseLine').onclick=add})</script>
